-- Add Benders decomposition, Dantzig-Wolfe decomposition, column generation, branch-and-price and branch-price-and-cut
-- (editorial scope TOPIC_BENDERS / TOPIC_DANTZIG_WOLFE / TOPIC_COLUMN_GENERATION / TOPIC_BRANCH_PRICE / TOPIC_BRANCH_PRICE_CUT).
-- Placement: Benders, branch-and-price and branch-price-and-cut go to MF_DISCRETE_EXACT (they solve mixed-integer problems and are
-- bound-and-gap based, like M_OUTER_APPROX_MINLP which is also a master-cut scheme). Dantzig-Wolfe and column generation go to
-- MF_LP_QP_CONIC: both are algorithms for linear programs (restricted master LP plus pricing), and their use inside integer programming is
-- expressed by related_method_ids to branch-and-price rather than by a second parent. M_BRANCH_BOUND / M_BRANCH_CUT are not duplicated.
-- Not added: homogeneous self-dual embedding (TOPIC_HOMOGENEOUS_EMBEDDING) is a reformulation used inside interior-point solvers (a primitive of
-- M_PRIMAL_DUAL_CONIC / M_BARRIER_LP_QP, docs/identity-granularity.md), so it gets no methods row.
-- No implementation rows: no existing implementation row has a confirmed API for these decompositions.
PRAGMA foreign_keys = ON;

INSERT INTO sources (
  source_id, source_type, title, author_or_organization, publication_date,
  accessed_date, url, supported_claim, source_quality, notes, currentness_status
) VALUES
('S134', 'original_paper', 'Partitioning procedures for solving mixed-variables programming problems', 'J. F. Benders', '1962-01-01', '2026-10-10', 'https://doi.org/10.1007/BF01386316', 'Benders decomposition: a mixed-variables problem is partitioned into a problem in the complicating variables and a linear problem in the remaining variables, solved by alternating between them.', 'primary', 'Numerische Mathematik 4, 238-252 (1962), DOI 10.1007/BF01386316. Title, volume and pages confirmed on 2026-10-10 against the DOI landing citation as reported by search (a 2005 reprint in Computational Management Science, DOI 10.1007/s10287-004-0020-y, carries the same citation). Month of publication not confirmed from an official listing, so publication_date is the year only.',
  'historical_primary'),
('S135', 'original_paper', 'Decomposition principle for linear programs', 'George B. Dantzig; Philip Wolfe', '1960-02-01', '2026-10-10', 'https://doi.org/10.1287/opre.8.1.101', 'Dantzig-Wolfe decomposition principle: a linear program with block structure is split into subprograms solved in alternation with a coordinating (master) program; the coordinator process is finite.', 'primary', 'Operations Research 8(1), 101-111 (1960), DOI 10.1287/opre.8.1.101. Confirmed on 2026-10-10 against the RePEc/IDEAS listing of the INFORMS record (February issue). Not to be confused with the Econometrica 29 (1961) paper by the same authors.',
  'historical_primary'),
('S136', 'original_paper', 'A linear programming approach to the cutting-stock problem', 'P. C. Gilmore; R. E. Gomory', '1961-01-01', '2026-10-10', 'https://doi.org/10.1287/opre.9.6.849', 'Column generation for the cutting-stock LP: a technique that always computes with a matrix having no more columns than rows, generating the needed pattern columns by a pricing step.', 'primary', 'Operations Research 9(6), 849-859 (1961), DOI 10.1287/opre.9.6.849. Confirmed on 2026-10-10 against the RePEc/IDEAS listing of the INFORMS record. Month not recorded (issue is November-December); publication_date is the year only. Part II is Operations Research 11(6), 863-888 (1963) and is a different paper.',
  'historical_primary'),
('S137', 'original_paper', 'Branch-and-price: column generation for solving huge integer programs', 'Cynthia Barnhart; Ellis L. Johnson; George L. Nemhauser; Martin W. P. Savelsbergh; Pamela H. Vance', '1998-06-01', '2026-10-10', 'https://doi.org/10.1287/opre.46.3.316', 'Branch-and-price: integer programs with a huge number of variables solved by column generation inside branch-and-bound, with branching rules compatible with the pricing problem; gives tighter LP relaxations and can remove symmetry for some model classes.', 'primary', 'Operations Research 46(3), 316-329 (1998), DOI 10.1287/opre.46.3.316. Confirmed on 2026-10-10 against the RePEc/IDEAS listing and the INFORMS page (June issue).',
  'historical_primary'),
('S138', 'original_paper', 'Selected topics in column generation', 'Marco E. Lubbecke; Jacques Desrosiers', '2005-12-01', '2026-10-10', 'https://doi.org/10.1287/opre.1050.0234', 'Survey of column generation biased toward integer programming, covering Dantzig-Wolfe decomposition and the dual point of view.', 'primary', 'Operations Research 53(6), 1007-1023 (2005), DOI 10.1287/opre.1050.0234. Confirmed on 2026-10-10 against the RePEc/IDEAS listing and the INFORMS reference page. The full text was not read; only the survey scope stated in the abstract is used.',
  'historical_primary'),
('S139', 'original_paper', 'A primer in column generation', 'Jacques Desrosiers; Marco E. Lubbecke', '2005-01-01', '2026-10-10', 'https://doi.org/10.1007/0-387-25486-2_1', 'Tutorial on column generation in linear and integer programming: Dantzig-Wolfe decomposition and Lagrangian relaxation embedded in branch-and-bound, with branching and cutting rules derived from a compact formulation.', 'primary', 'Chapter 1 in G. Desaulniers, J. Desrosiers, M. M. Solomon (eds.), Column Generation, Springer, 2005, pp. 1-32, DOI 10.1007/0-387-25486-2_1. Confirmed on 2026-10-10 against the RePEc/EconPapers listing and the DOI. The full text was not read; the branch-price-and-cut claim is limited to the scope stated in its abstract (branching and cutting rules in a column-generation setting). The Wiley Encyclopedia of OR and MS entry Branch-Price-and-Cut Algorithms by the same authors was located but its year and DOI could not be confirmed, so it is not recorded.',
  'historical_primary');

INSERT INTO methods (
  method_id, name_ja, name_en, aliases, method_family_id, method_level, summary, problem_classes, required_assumptions, derivative_information, variable_types, constraint_support, convex_fit, nonconvex_applicability, solution_scope, determinism, exactness, theoretical_guarantee, optimality_certificate, scalability, memory_tendency, per_iteration_cost, evaluation_pattern, parallelism, initialization_sensitivity, hyperparameter_sensitivity, scaling_sensitivity, noise_robustness, discontinuity_robustness, constraint_violation_handling, warm_start, online_use, strengths, weaknesses, typical_failures, avoid_conditions, first_choice_conditions, second_choice_conditions, switch_signals, beginner_level, tuning_difficulty, implementation_difficulty, explainability, stopping_criteria, diagnostic_metrics, related_method_ids, parent_method_id, child_method_ids, reference_source_ids, confidence, last_verified
) VALUES
('M_BENDERS', 'Benders分解', 'Benders decomposition', 'Benders decomposition;Benders partitioning;L-shaped method', 'MF_DISCRETE_EXACT', 'variant', '難しい変数(整数など)を扱うmasterと、それを固定した線形のsubproblemに分け、subproblemの双対情報からmasterへcut(optimality/feasibility cut)を足していく分解法。', 'MILP;mixed_variable;two_stage_stochastic_LP', '変数を「複雑化変数」と、固定すると線形(双対が使える)になる変数に分けられる。subproblemの双対解またはray(実行不能の証拠)を取り出せること。', 'model_coefficients', 'binary;integer;mixed', 'linear', 'relaxation_dependent', 'unknown', 'global_certificate', 'deterministic', 'exact_with_tolerance', '元論文は、masterと線形subproblemの往復で混合変数問題を解く手続きを与える(Benders 1962)。有限回の反復で最適性を示せるかは、複雑化変数の領域が有限であるなどの条件に依存する。凸な非線形subproblemへの一般化はこの出典の範囲外。', 'master下界とsubproblem上界(incumbent)のgap', 'highly_instance_dependent', 'medium_master_grows_with_cuts', 'master(MILP)を解くコストが支配的になり得る。subproblemはLPで安価。', 'master解 -> subproblem(LP)解 -> cut追加の反復。', 'subproblem_parallel_when_separable', 'low', 'low', 'medium', 'not_applicable_input_data_sensitivity', 'not_applicable', 'feasibility_tolerances', 'yes_by_solver', 'conditional', '複雑化変数を除くと線形になる構造(二段階確率計画の第二段など)を分離できる;subproblemが独立なら並列化できる;gapで品質を示せる', 'masterに入れるcutが増えるとmasterが重くなる;cutが弱いと収束が遅い(振動);定式化と実装の工夫(cut選択、安定化)に依存', 'slow_convergence_weak_cuts;master_blowup;degenerate_subproblem_duals', '分離できる構造がない;subproblemが整数を含み双対が使えない;複雑化変数が多くmasterが元問題と同程度に難しい', '複雑化変数を固定すると線形(または凸)になり、subproblemの双対が使える混合整数・確率計画で、一括のbranch and cutが大きすぎる場合。', '一括のMILPがsolverで解ける規模なら、まずbranch and cutで足りる。', 'master反復が増えてもgapが縮まない;cutが大量に溜まる;subproblem双対が不安定。', 'low', 'medium', 'high', 'high', 'optimality_gap;time;iteration_limit', 'master_bound;subproblem_bound;gap;cuts_added;master_solve_time', 'M_BRANCH_CUT;M_OUTER_APPROX_MINLP;M_DANTZIG_WOLFE;M_BRANCH_BOUND', 'MF_DISCRETE_EXACT', '', 'S134', 'medium', '2026-10-10'),
('M_DANTZIG_WOLFE', 'Dantzig-Wolfe分解', 'Dantzig-Wolfe decomposition', 'Dantzig-Wolfe decomposition;Dantzig-Wolfe;DW decomposition', 'MF_LP_QP_CONIC', 'variant', 'ブロック角構造を持つ線形計画を、結合制約だけを持つmaster(各ブロックの極点・極方向の凸結合)と、ブロックごとのsubproblemに分け、subproblemを価格付け問題として解いて列を足す分解法。', 'LP;block_angular_LP', '結合制約と、独立に近いブロック制約に分けられる線形計画。各ブロックの実行可能領域が多面体として扱えること。', 'model_coefficients', 'continuous', 'linear', 'primary', 'unknown', 'convex_global', 'deterministic', 'exact_with_tolerance', '元論文は、LPを副問題と調整(master)問題の交互解に分けた反復が有限であることを示している(Dantzig and Wolfe 1960)。', 'masterの双対変数と各subproblemの被約費用(prices)', 'high_for_block_structure', 'medium_columns_accumulate', 'restricted masterのLP解とブロックごとのpricing LPの和。', 'restricted master LP -> 双対価格 -> pricing -> 負の被約費用の列を追加、の反復。', 'pricing_blocks_parallel', 'low', 'low', 'medium', 'not_applicable_input_data_sensitivity', 'not_applicable', 'feasibility_tolerances', 'yes_for_added_columns', 'conditional', 'ブロック構造を直接使える;ブロックを並列に解ける;masterの列が増えるだけで基底を再利用できる', '収束末尾で停滞(tailing-off)しやすい;ブロック構造が弱いと利点が小さい;現代の一括LP solverの方が速い場合も多い', 'tailing_off;degenerate_master;dual_oscillation', 'ブロック構造がない;一括のsimplex/barrierで十分解ける規模', '明確なブロック角構造を持つ巨大LPで、ブロックごとの解法を使いたい、または列生成の土台として整数計画の緩和を強くしたいとき。', '構造が弱い一般LPでは、simplexやbarrierを先に試す。', '反復が多いのに目的が動かない;masterが退化する;双対が振動する。', 'medium', 'medium', 'high', 'high', 'reduced_cost_nonnegative;optimality_gap;iteration_limit', 'master_objective;min_reduced_cost;columns_added;lagrangian_bound', 'M_COLUMN_GENERATION;M_SIMPLEX;M_BENDERS', 'MF_LP_QP_CONIC', '', 'S135;S138;S139', 'medium', '2026-10-10'),
('M_COLUMN_GENERATION', '列生成', 'Column generation', 'column generation;delayed column generation;pricing problem approach', 'MF_LP_QP_CONIC', 'variant', '列(変数)が膨大なLPを、一部の列だけの制限master問題と、被約費用が負の列を探すpricing問題の反復で解く方法。切断在庫問題のGilmore-Gomoryが起源。', 'LP;LP_relaxation_of_set_partitioning;cutting_stock', '列の集合を陽に持たず、双対価格から有効な列を見つけるpricing問題(しばしば別の最適化問題)を解けること。', 'model_coefficients', 'continuous', 'linear', 'primary', 'unknown', 'convex_global', 'deterministic', 'exact_with_tolerance', 'Gilmore and Gomory(1961)は、列数が行数を超えない行列だけで切断在庫LPを計算する手法を与えた。pricingが厳密に解ければ、被約費用が非負になった時点でLPの最適性が示される(simplex法の最適性条件による)。', 'pricingの最小被約費用が非負であること', 'high_for_implicit_columns', 'medium_columns_accumulate', 'restricted masterのLP再最適化とpricing問題の解(後者が支配的になり得る)。', 'restricted master LP -> 双対価格 -> pricing -> 負の被約費用の列を追加、の反復。', 'pricing_parallel_when_separable', 'low', 'low', 'medium', 'not_applicable_input_data_sensitivity', 'not_applicable', 'feasibility_tolerances', 'yes_for_added_columns', 'conditional', '変数を陽に列挙せずに巨大LPを解ける;整数計画の強いLP緩和を与える定式化に使える;pricingに構造(最短路、knapsackなど)を使える', '収束末尾の停滞(tailing-off)と双対の不安定性;pricing問題自体が難しい場合がある;整数解を得るには分枝(branch and price)が別途必要', 'tailing_off;dual_oscillation;pricing_too_slow;degenerate_master', '変数数が小さく陽に持てる;pricing問題に効率的な解法がない', '変数が指数的に多いが、被約費用が負の列を構造を使って効率よく探せるLP(切断在庫、乗務員・経路計画の緩和など)。', '列数が陽に扱える規模なら、通常のLP solverで十分。', '目的の改善が小さい反復が長く続く;pricingが全体時間を占める;masterが退化する。', 'medium', 'medium', 'high', 'high', 'reduced_cost_nonnegative;iteration_limit;time', 'master_objective;min_reduced_cost;columns_added;pricing_time;lagrangian_bound', 'M_DANTZIG_WOLFE;M_BRANCH_PRICE;M_SIMPLEX', 'MF_LP_QP_CONIC', '', 'S136;S138;S139', 'medium', '2026-10-10'),
('M_BRANCH_PRICE', '分枝価格法', 'Branch and price', 'branch-and-price;branch and price;B&P', 'MF_DISCRETE_EXACT', 'variant', 'branch and boundの各節点の緩和を列生成で解く整数計画の厳密解法。変数が非常に多い定式化を使い、分枝規則がpricing問題を壊さないよう設計する。', 'MILP;IP_with_huge_number_of_variables;set_partitioning;cutting_stock;routing', 'Dantzig-Wolfe型などの拡張定式化が構成でき、各節点で列生成が実行でき、分枝後もpricingが扱える分枝規則があること。', 'model_coefficients', 'binary;integer;mixed', 'linear', 'relaxation_dependent', 'unknown', 'global_certificate', 'deterministic', 'exact_with_tolerance', '列生成による節点緩和でbranch and boundの枠組みに載るため、探索完了時にincumbentと下界で最適性を示せる。元論文は、LP緩和が強くなる、一部のモデル類で対称性を除ける、と報告している(Barnhart et al. 1998)。一般に常に速いわけではない。', '節点緩和(列生成)の下界とincumbentのgap', 'highly_instance_dependent', 'high_tree_and_columns', '節点ごとに列生成(restricted masterとpricingの反復)を行うため重い。', '節点: 列生成でLP緩和を解く -> 分枝 -> 子節点で列を再利用して再最適化。', 'tree_parallelism', 'low', 'low', 'medium', 'not_applicable_input_data_sensitivity', 'not_applicable', 'feasibility_tolerances', 'yes_for_child_nodes', 'conditional', '拡張定式化によりLP緩和の下界が強くなる場合がある;対称性を減らせる場合がある;gapで品質を示せる', '実装が複雑(分枝規則とpricingの整合、列管理);節点ごとの列生成で重い;tailing-offが木全体に響く', 'tailing_off;branching_breaks_pricing;column_pool_blowup;weak_extended_relaxation', 'コンパクトな定式化で汎用MILP solverが十分に解ける;pricing問題が効率的に解けない', 'コンパクト定式化の緩和が弱く、変数が指数的に多い拡張定式化(経路、パターン、スケジュール)でpricingを構造的に解ける整数計画。', 'まず汎用のbranch and cutで解けるかを確かめ、緩和の弱さが支配的なときに検討する。', '汎用solverのroot gapが大きい;変数を列挙する定式化の方が緩和が強い。', 'low', 'high', 'high', 'medium', 'optimality_gap;time;node_limit', 'best_bound;incumbent;gap;nodes;columns_generated;pricing_time;root_bound', 'M_COLUMN_GENERATION;M_BRANCH_BOUND;M_BRANCH_CUT;M_BRANCH_PRICE_CUT;M_DANTZIG_WOLFE', 'MF_DISCRETE_EXACT', '', 'S137;S138;S139', 'medium', '2026-10-10'),
('M_BRANCH_PRICE_CUT', '分枝価格カット法', 'Branch-price-and-cut', 'branch-price-and-cut;branch-and-price-and-cut;BPC', 'MF_DISCRETE_EXACT', 'variant', '分枝価格法に切除平面(cut)を組み合わせ、節点の列生成緩和をcutで強める整数計画の厳密解法。cutがpricing問題を壊さない設計が要点。', 'MILP;IP_with_huge_number_of_variables;routing;scheduling', '分枝価格法の前提に加え、cutを加えても(双対価格の変化を含めて)pricingが扱えること、または既存の価格付けへ組み込めること。', 'model_coefficients', 'binary;integer;mixed', 'linear', 'relaxation_dependent', 'unknown', 'global_certificate', 'deterministic', 'exact_with_tolerance', '列生成節点緩和とcutを組み合わせたbranch and boundの枠組みに載る。枝刈りと下界の妥当性はcutの妥当性とpricingの厳密性に依存する。分枝・cut規則をコンパクト定式化から導く考え方は、Desrosiers and Lubbecke(2005)の入門が扱う範囲で、個別の効果は出典の範囲外。', 'cut付き列生成緩和の下界とincumbentのgap', 'highly_instance_dependent', 'high_tree_columns_and_cuts', '節点ごとに列生成とcut分離を繰り返すため重い。', '節点: 列生成とcut分離の反復でLP緩和を強める -> 分枝。', 'tree_parallelism', 'low', 'low', 'medium', 'not_applicable_input_data_sensitivity', 'not_applicable', 'feasibility_tolerances', 'yes_for_child_nodes', 'conditional', '拡張定式化の緩和をcutでさらに強められる;gapで品質を示せる', '分枝価格法より更に実装が複雑;cutがpricingを難しくする(価格付けに追加の双対が入る)ことがある', 'cut_breaks_pricing;tailing_off;column_and_cut_pool_blowup;weak_cuts', '分枝価格法だけでgapが十分に閉じる;cutの分離が難しい', '分枝価格法のroot gapがcutで有意に縮められ、pricingがcut由来の双対を扱える整数計画。', 'cutが不要または効かないなら分枝価格法で足りる。', '分枝価格法のroot gapが残る;分離できる妥当不等式が見つかる。', 'low', 'high', 'high', 'medium', 'optimality_gap;time;node_limit', 'best_bound;incumbent;gap;nodes;columns_generated;cuts_added;pricing_time', 'M_BRANCH_PRICE;M_BRANCH_CUT;M_COLUMN_GENERATION', 'MF_DISCRETE_EXACT', '', 'S139;S137;S138', 'medium', '2026-10-10');

UPDATE methods
SET child_method_ids = 'M_BRANCH_BOUND;M_BRANCH_CUT;M_OUTER_APPROX_MINLP;M_SPATIAL_BRANCH_BOUND;M_BENDERS;M_BRANCH_PRICE;M_BRANCH_PRICE_CUT'
WHERE method_id = 'MF_DISCRETE_EXACT';
UPDATE methods
SET child_method_ids = 'M_SIMPLEX;M_DUAL_SIMPLEX;M_BARRIER_LP_QP;M_PDLP;M_ACTIVE_SET_QP;M_ADMM_QP;M_PRIMAL_DUAL_CONIC;M_DANTZIG_WOLFE;M_COLUMN_GENERATION'
WHERE method_id = 'MF_LP_QP_CONIC';

