('TERM_COLUMN_GENERATION', 'method', 'M_COLUMN_GENERATION', '列生成', 'Column generation', '[]',
 '["delayed column generation","pricing problem approach"]', '["pricing問題","restricted master","被約費用"]', '[]', '[]',
